preConditionHook:
// WANING MOMENTUM IN THE SWINGS THEMSELVES: the gains between successive swing
// highs are shrinking, so take profits on the long. With three confirmed swing
// highs, the newest increment (pivot 1 minus pivot 2) is less than
// shrinkFraction of the one before it (pivot 2 minus pivot 3). Short is the
// mirror on three swing lows.
//
// Brooks's worked numbers -- the second peak eight ticks above the first, the
// third only three above the second -- put the fraction well under 0.5; 0.5 is
// the candidate's default. Also usable as a negative entry filter, which is the
// per-placement negate toggle rather than a second rule.
//
// BOTH INCREMENTS ARE REQUIRED POSITIVE (pivot 1 above pivot 2 above pivot 3).
// The merged pseudocode states only the first; without the second the
// right-hand side can be negative and the comparison stops meaning "shrinking".
//
// THE PIVOT SCAN IS HAND-ROLLED because occurrence 3 and beyond is UNMEASURED in
// the register, exactly as SwingPivotTarget does it. MEASURED
// (EL_Swing_Probe.txt / el_swing_output1.txt, @ES 60 min): the pivot bar is AT
// OR ABOVE the swingStrength older bars and STRICTLY ABOVE the swingStrength
// newer bars -- bars-ago indexing, so the newer bars are the smaller k and take
// el_gt / el_lt, the older el_ge / el_le; confirmation lag exactly
// swingStrength; candidate offsets swingStrength..lookbackBars-1; the
// neighbourhood reaches swingStrength bars past the window, so the deepest bar
// touched is lookbackBars - 1 + swingStrength. No early break, matching the
// twin, and the counters cap the pivots kept at three. The comparisons carry the
// 2.22e-12 relational tolerance. The low side's tie sense is the mirror of the
// measured high-side rule. The -1 initialisers are inert here because the
// nHiPiv >= 3 gate covers them.
pivS = (int)swingStrength;
pivW = (int)lookbackBars;
nHiPiv = 0;
nLoPiv = 0;
hiPx1 = -1.0;
hiPx2 = -1.0;
hiPx3 = -1.0;
loPx1 = -1.0;
loPx2 = -1.0;
loPx3 = -1.0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool okHi = true;
    bool okLo = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_gt(high[j], high[k])) okHi = false;
        if (!el_lt(low[j], low[k])) okLo = false;
    }
    for (int k = j + 1; k <= j + pivS; ++k) {
        if (!el_ge(high[j], high[k])) okHi = false;
        if (!el_le(low[j], low[k])) okLo = false;
    }
    if (okHi && nHiPiv < 3) {
        nHiPiv = nHiPiv + 1;
        if (nHiPiv == 1) hiPx1 = high[j];
        if (nHiPiv == 2) hiPx2 = high[j];
        if (nHiPiv == 3) hiPx3 = high[j];
    }
    if (okLo && nLoPiv < 3) {
        nLoPiv = nLoPiv + 1;
        if (nLoPiv == 1) loPx1 = low[j];
        if (nLoPiv == 2) loPx2 = low[j];
        if (nLoPiv == 3) loPx3 = low[j];
    }
}
shrinkUp = (nHiPiv >= 3) && el_gt(hiPx1, hiPx2) && el_gt(hiPx2, hiPx3)
    && el_lt(hiPx1 - hiPx2, shrinkFraction * (hiPx2 - hiPx3));
shrinkDn = (nLoPiv >= 3) && el_lt(loPx1, loPx2) && el_lt(loPx2, loPx3)
    && el_lt(loPx2 - loPx1, shrinkFraction * (loPx3 - loPx2));
